mapper.select:
select id, session_id, seq_no, event_kind, visibility, cast(public_payload_json as char) as public_payload_json, actor_user_id, occurred_at from edu_session_event where session_id = #{sessionId} and seq_no > #{afterSeq}
and visibility = 'PUBLIC'
order by seq_no asc

select coalesce(max(seq_no), 0)
from edu_session_event
where session_id = #{sessionId}

